args.command:
python3 - <<'EOF'
import unicodedata
text=open('/tmp/probe_f/out.txt',encoding='utf-8').read()
def dispw(s):
    w=0
    for ch in s:
        w+= 2 if unicodedata.east_asian_width(ch) in 'WF' else 1
    return w
for i,l in enumerate(text.split('\n')):
    if not l or l[0]=='≖': 
        if l: print(i,'BORDER chars:',len(l))
        continue
    cells=l.split('⋮')[1:-1]
    out=[]
    for c in cells:
        content=c[1:-1]  # strip the single leading/trailing space
        out.append(f"content={content!r} chars={len(content)} bytes={len(content.encode())} dispw={dispw(content)} cellchars={len(c)}")
    print(i, ' | '.join(out))
EOF

